    initial_string = "##.#.."
    rules = [
        {"pattern": ".#", "replacement": "#.", "index": 0},
        {"pattern": "###...", "replacement": "", "index": 1}
    ]

    string = initial_string
    applied_rules = []

    while string:
        found = False
        for rule in rules:
